/**
 * Build hand-authored teach rewrites for Grade 6 Math Units 2–11.
 * Source pedagogy: /tmp/hand_content_partial.json (generated by authoring scripts)
 *   → copied to scripts/data/grade6-math-hand-teach.json
 * IDs: scripts/data/_g6_math_ids.json
 * Independent practice: scripts/lib/grade6-math-practice.mjs
 *
 * Run: node scripts/build-math-hand-rewrites.mjs
 * Do NOT re-run gen-grade6-math-year.mjs over these units without merge skip.
 */
import { readFileSync, writeFileSync, mkdirSync, copyFileSync, existsSync } from "node:fs";
import { mathIndepPractice } from "./lib/grade6-math-practice.mjs";

const COURSE_ID = "cmuh9bwto03qledantwv3vsfd";
const UNIT_META = {
  2: "Arithmetic with Rational Numbers",
  3: "Rates and Percentages",
  4: "Exponents and Order of Operations",
  5: "Negative Numbers",
  6: "Variables & Expressions",
  7: "Equations & Inequalities",
  8: "Plane Figures",
  9: "Coordinate Plane",
  10: "3D Figures",
  11: "Data and Statistics",
};

const srcJson = existsSync("scripts/data/grade6-math-hand-teach.json")
  ? "scripts/data/grade6-math-hand-teach.json"
  : "/tmp/hand_content_partial.json";
if (!existsSync("scripts/data/grade6-math-hand-teach.json") && existsSync("/tmp/hand_content_partial.json")) {
  copyFileSync("/tmp/hand_content_partial.json", "scripts/data/grade6-math-hand-teach.json");
}

const raw = JSON.parse(readFileSync("scripts/data/grade6-math-hand-teach.json", "utf8"));
const ids = JSON.parse(readFileSync("scripts/data/_g6_math_ids.json", "utf8"));

function escSql(s) {
  return String(s).replace(/'/g, "''");
}

function formatIndependent(unitN, title, seed) {
  const items = mathIndepPractice(unitN, title, seed);
  let md = `## Independent practice\n\nComplete each item. Show your work.\n\n`;
  items.forEach((it, i) => {
    md += `${i + 1}. ${it.q}\n`;
  });
  md += `\n### Answer key (try first)\n\n`;
  items.forEach((it, i) => {
    md += `${i + 1}. ${it.a}\n`;
  });
  return md;
}

function buildFull(unitN, orderInUnit, title, pack) {
  const meta = UNIT_META[unitN];
  const header = `# ${title}\n\n*Grade 6 Mathematics · Unit ${unitN} of 11 · ${meta} · Lesson ${orderInUnit}*\n\n`;
  const independent = formatIndependent(unitN, title, `u${unitN}:${title}`);
  return `${header}${pack.teach_core.trim()}\n\n${independent.trim()}\n\n${pack.exit.trim()}\n`;
}

let sql = `-- Grade 6 Math Units 2–11: hand-authored Teach / Warm-up / Guided / Exit + skill Check MC.
-- Keeps existing lesson IDs and titles. Independent practice from skill banks.
-- UPDATE content + objectives + description + Question rows. Preserve videoUrl.
-- Do NOT run db:setup. Safe for production D1 (prosperprep-school).
-- Source: scripts/data/grade6-math-hand-teach.json — do not Mad-Lib overwrite via gen-grade6-math-year.mjs.

`;

const lessonsOut = [];
let rewritten = 0;
const forbidden = [/khan/i, /ckla/i, /ckhg/i, /\bgay\b/i, /\btrans\b/i, /lgbt/i, /lesbian/i, /bisexual/i];

for (let unitN = 2; unitN <= 11; unitN++) {
  const sk = `unit-${unitN}`;
  const lessonIds = ids[sk] || [];
  lessonIds.forEach((meta, idx) => {
    const key = `${unitN}|${meta.title}`;
    const pack = raw[key];
    if (!pack) throw new Error(`Missing hand pack for ${key}`);
    const orderInUnit = idx + 1;
    const content = buildFull(unitN, orderInUnit, meta.title, pack);
    for (const re of forbidden) {
      if (re.test(content)) console.warn("WARN forbidden", re, meta.title);
    }
    sql += `-- Unit ${unitN} L${orderInUnit}. ${meta.title} (${meta.id})\n`;
    sql += `UPDATE "Lesson" SET "content" = '${escSql(content)}', "objectives" = '${escSql(pack.objectives)}', "description" = '${escSql(pack.description)}' WHERE "id" = '${meta.id}' AND "courseId" = '${COURSE_ID}';\n\n`;

    const qids = meta.questionIds || [];
    pack.questions.forEach((q, qi) => {
      const qid = qids[qi];
      if (!qid) throw new Error(`Missing question id for ${meta.title} Q${qi + 1}`);
      const choicesJson = JSON.stringify(q.choices);
      sql += `INSERT INTO "Question" ("id","lessonId","quizId","type","prompt","choices","correctIndex","explanation","points","order") VALUES ('${qid}','${meta.id}',NULL,'MULTIPLE_CHOICE','${escSql(q.prompt)}','${escSql(choicesJson)}',${q.correctIndex},'${escSql(q.explanation)}',1,${qi + 1}) ON CONFLICT("id") DO UPDATE SET "prompt"=excluded."prompt","choices"=excluded."choices","correctIndex"=excluded."correctIndex","explanation"=excluded."explanation","points"=excluded."points","order"=excluded."order","lessonId"=excluded."lessonId","quizId"=excluded."quizId";\n`;
      for (const re of forbidden) {
        const blob = q.prompt + q.choices.join(" ") + q.explanation;
        if (re.test(blob)) console.warn("WARN forbidden Q", re, meta.title);
      }
    });
    sql += `\n`;
    rewritten++;
    lessonsOut.push({ unit: unitN, id: meta.id, title: meta.title, orderInUnit });
  });
}

mkdirSync("migrations", { recursive: true });
writeFileSync("migrations/0016_grade6_math_units2_11_teach_rewrite.sql", sql);
mkdirSync("docs/curriculum/math-hand", { recursive: true });
writeFileSync(
  "docs/curriculum/grade-6-math-units2-11-rewrite.md",
  `# Grade 6 Math Units 2–11 teach rewrite

**Shipped via migration 0016** · ${rewritten} lessons hand-authored (Warm-up / Teach / Guided / Exit / Check MC).
Independent practice retained from \`grade6-math-practice.mjs\` skill banks.

## Pattern
Same as Unit 1 Ratios (migration 0014): keep IDs/titles; replace Mad-Libs \`buildLessonBody()\` mush with skill-specific pedagogy.
Do **not** re-run \`gen-grade6-math-year.mjs\` without the hand-merge skip for units 2–11.

## Quality bar
\`docs/curriculum/grade-6-ratios-sample-what-is-a-ratio.md\` + Unit 1 source.
No Khan/CKLA in student text; no LGBTQ themes; original Prosper Prep prose.
`
);

console.log(JSON.stringify({ rewritten, sqlBytes: Buffer.byteLength(sql), units: 10 }, null, 2));
